for name,p in pairs(BY_NAME) do
  local compact=name:gsub("_","")
  if BY_NAME[compact]==nil then BY_NAME[compact]=p end
end

local function norm(v)
  return tostring(v or ""):upper():gsub("[%s%-]+","_"):gsub("[^A-Z0-9_]","")
end

BY_NAME["FAINT_ATTACK"]=BY_ID[185]
