function M.get(moveId,def)
  local n=norm(moveId)
  local id=tonumber(moveId)
  local p=(id and BY_ID[id]) or BY_NAME[n] or BY_NAME[n:gsub("_","")]
  if not p and type(def)=="table" then
    local did=tonumber(def.id or def.moveId or def.index)
    local dn=norm(def.name or def.displayName or def.id)
    p=(did and BY_ID[did]) or BY_NAME[dn] or BY_NAME[dn:gsub("_","")]
  end
  return p
end

function M.class(moveId,def)
  local p=M.get(moveId,def)
  return p and p.class or nil
end

M.byId=BY_ID
M.byName=BY_NAME
return M
